#!/usr/bin/env python3
"""Patches the Android project generated by `flutter create` (run from the app/ folder).
Adds permissions, url_launcher queries, the app label and a safe minSdk."""
import re, sys, pathlib

import argparse
ap = argparse.ArgumentParser()
ap.add_argument("root", nargs="?", default="android")
ap.add_argument("--label", default="SmartFundi")
ap.add_argument("--app-id", default=None)
args = ap.parse_args()
root = pathlib.Path(args.root)
man = root / "app/src/main/AndroidManifest.xml"
s = man.read_text()

perms = """
    <uses-permission android:name="android.permission.INTERNET"/>
    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION"/>
    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION"/>
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>
    <uses-permission android:name="android.permission.CAMERA"/>
    <uses-feature android:name="android.hardware.camera" android:required="false"/>"""
if "ACCESS_FINE_LOCATION" not in s:
    s = re.sub(r"(<manifest[^>]*>)", lambda m: m.group(1) + perms, s, count=1)

queries = """
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="https"/></intent>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="http"/></intent>
        <intent><action android:name="android.intent.action.DIAL"/><data android:scheme="tel"/></intent>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="tel"/></intent>
        <intent><action android:name="android.intent.action.SENDTO"/><data android:scheme="sms"/></intent>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="sms"/></intent>"""
if 'android:scheme="sms"' not in s:
    if "</queries>" in s:
        s = s.replace("</queries>", queries + "\n    </queries>", 1)
    else:
        s = s.replace("</manifest>", "    <queries>" + queries + "\n    </queries>\n</manifest>", 1)

s = re.sub(r'android:label="[^"]*"', f'android:label="{args.label}"', s, count=1)
man.write_text(s)

for name in ("app/build.gradle", "app/build.gradle.kts"):
    f = root / name
    if f.exists():
        g = f.read_text()
        g = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 23", g)
        g = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 23", g)
        if args.app_id:
            g = re.sub(r'applicationId\s*=\s*"[^"]+"', f'applicationId = "{args.app_id}"', g)
            g = re.sub(r'applicationId\s+"[^"]+"', f'applicationId "{args.app_id}"', g)
        f.write_text(g)
print("Android project patched")
